import{c as i,$ as r,Q as o,j as n,g as t,o as s,n as l,m as d}from"./chunks/framework.Ce_49mA8.js";const c="/img/en/front/warehouse.webp",k=JSON.parse('{"title":"Raw Materials & Inventory","description":"Universal inventory management, batch purchases, Moving Average Cost (MAC), freight allocation, and barcode label printing in OmniCraft ERP.","frontmatter":{"title":"Raw Materials & Inventory","description":"Universal inventory management, batch purchases, Moving Average Cost (MAC), freight allocation, and barcode label printing in OmniCraft ERP.","datePublished":"2026-08-20","dateModified":"2026-11-25","order":2},"headers":[],"relativePath":"docs/resources/warehouse.md","filePath":"docs/resources/warehouse.md","lastUpdated":1795564800000}'),h={name:"docs/resources/warehouse.md"},u={id:"raw-materials-inventory",tabindex:"-1"};function g(p,e,m,f,b,y){const a=r("DocIcon");return o(),n("div",null,[t("h1",u,[s(a,{name:"warehouse"}),e[0]||(e[0]=l(" Raw Materials & Inventory ",-1)),e[1]||(e[1]=t("a",{class:"header-anchor",href:"#raw-materials-inventory","aria-label":'Permalink to "Raw Materials & Inventory"'},"​",-1))]),e[2]||(e[2]=d('<figure class="doc-image craft-window-frame" data-title="Raw Materials and Inventory — OmniCraft ERP"><img src="'+c+'" alt="Main window of the Warehouse tab"><figcaption>Main window of the Warehouse tab</figcaption></figure><p>The <strong>&quot;Warehouse&quot;</strong> tab serves as the central hub of physical supply management across your business. Whether you stock raw materials for manufacturing, spare parts and service consumables for repair studios, or packaged wholesale inventory for retail and e-commerce marketplaces, physical stock sitting on shelves represents frozen working capital.</p><p>In <strong>OmniCraft ERP</strong>, warehouse inventory does far more than count quantities in units, meters, or kilograms. It connects directly with managerial financial accounting: it computes true inventory valuation using the <strong>Moving Average Cost (MAC)</strong> method, equitably distributes shipping fees across line items, and generates automatic expense entries in the Cash Flow register (DDS).</p><hr><h2 id="costing-mechanics-moving-average-cost-mac" tabindex="-1">Costing Mechanics: Moving Average Cost (MAC) <a class="header-anchor" href="#costing-mechanics-moving-average-cost-mac" aria-label="Permalink to &quot;Costing Mechanics: Moving Average Cost (MAC)&quot;">​</a></h2><p>Supplier prices fluctuate constantly due to inflation, seasonal discounts, or changing order volumes. Pricing inventory strictly by the most recent invoice overvalues older stock; pricing by outdated legacy costs leads to hidden operating losses.</p><p>OmniCraft ERP implements the industrial accounting standard — <strong>Moving Average Cost (MAC)</strong>:</p><div class="craft-metaphor-card"><div class="metaphor-badge">&quot;Paint Can&quot; Analogy</div><p class="metaphor-lead">When two batches of identical paint are mixed, the cost per liter becomes an exact weighted average.</p><table class="craft-matrix-table" style="margin-top:1rem;"><thead><tr><th style="width:35%;">Inventory Batch</th><th style="width:20%;">Volume</th><th style="width:25%;">Purchase Price</th><th style="width:20%;">Total Cost</th></tr></thead><tbody><tr><td><strong>Existing on Shelf</strong></td><td>10 kg</td><td>$5.00/kg</td><td>$50.00</td></tr><tr><td><strong>New Batch Purchase</strong></td><td>10 kg</td><td>$7.00/kg</td><td>$70.00</td></tr><tr><td><strong>Total Balance (MAC)</strong></td><td><strong>20 kg</strong></td><td><strong>$6.00/kg</strong></td><td><strong>$120.00</strong></td></tr></tbody></table></div><p>Whenever materials are consumed by a product recipe or booked into a client service order, OmniCraft deducts them at the current moving average cost. You never need to track which specific historical box a piece came from—your profit margin is protected automatically.</p><div class="tip custom-block"><p class="custom-block-title">Shipping increases unit cost</p><p>Freight and courier delivery fees are not an abstract overhead expense; they are an intrinsic part of the material&#39;s acquisition cost. In OmniCraft ERP, delivery charges are automatically absorbed into the unit valuation of each stocked item.</p></div><hr><h2 id="industry-specific-inventory-workflows" tabindex="-1">Industry-Specific Inventory Workflows <a class="header-anchor" href="#industry-specific-inventory-workflows" aria-label="Permalink to &quot;Industry-Specific Inventory Workflows&quot;">​</a></h2><p>Depending on your chosen workspace profile, inventory adapts to your operational rhythm:</p><h3 id="production" tabindex="-1">Manufacturing &amp; Craft Workshops <a class="header-anchor" href="#production" aria-label="Permalink to &quot;Manufacturing &amp; Craft Workshops {#production}&quot;">​</a></h3><p>The warehouse holds raw materials that are physically transformed into finished goods:</p><ul><li><strong>Typical inventory:</strong> sheet metal, timber, genuine leather, textiles, pottery clay, 3D-printing filaments, thread, hardware, adhesives, and packaging boxes.</li><li><strong>Recipe integration:</strong> consumption norms defined in the &quot;Calculator&quot; module link directly to inventory stock cards. When an assembly batch is launched on the workbench, the software reserves required quantities and deducts exact millimeters, grams, or square decimeters upon job completion.</li></ul><h3 id="services" tabindex="-1">Service Centers &amp; Repair Studios <a class="header-anchor" href="#services" aria-label="Permalink to &quot;Service Centers &amp; Repair Studios {#services}&quot;">​</a></h3><p>The warehouse acts as a parts depot for replacement components and job supplies:</p><ul><li><strong>Typical inventory:</strong> LCD panels, flex cables, microchips, filters, brake pads, drive belts, copper pipes, plumbing fittings, solder, hardware assortments, and sanitizing chemicals.</li><li><strong>Service ticket integration:</strong> parts and materials are added directly into client work orders. OmniCraft deducts items from inventory the moment the ticket is completed, billing parts to the customer and recording income into Cash Flow.</li></ul><h3 id="trade" tabindex="-1">Retailers &amp; E-commerce Marketplace Sellers <a class="header-anchor" href="#trade" aria-label="Permalink to &quot;Retailers &amp; E-commerce Marketplace Sellers {#trade}&quot;">​</a></h3><p>The warehouse manages rapid merchandise turnover of pre-packaged goods:</p><ul><li><strong>Typical inventory:</strong> factory-packed merchandise, custom branded boxes, poly courier mailers, reinforced tape, protective void fill, and barcode labels.</li><li><strong>Stockout prevention:</strong> setting low-stock alert thresholds ensures timely reorders, preventing out-of-stock penalties and maintaining high storefront rankings on digital marketplaces.</li></ul><hr><h2 id="material-stock-card-smart-controls" tabindex="-1">Material Stock Card &amp; Smart Controls <a class="header-anchor" href="#material-stock-card-smart-controls" aria-label="Permalink to &quot;Material Stock Card &amp; Smart Controls&quot;">​</a></h2><p>Adding a new item to your catalog is done via the <strong>&quot;+&quot; (New Item)</strong> button in the top toolbar. Each material card contains essential parameters:</p><ul><li><strong>Name:</strong> clear operational title (e.g., <em>“T-Slot Extruded Aluminum Profile 20×20 mm”</em> or <em>“OLED Display Assembly Module”</em>).</li><li><strong>SKU / Barcode:</strong> unique internal inventory code. If left blank, OmniCraft automatically generates a sequential SKU formatted as <code>SKU-0001</code>, preventing duplicate lookup errors during barcode scanning.</li><li><strong>Category:</strong> functional grouping (e.g., <em>“Metals”</em>, <em>“Hardware”</em>, <em>“Electronics”</em>, <em>“Packaging”</em>). Categories can be customized directly from the card dialog.</li><li><strong>Unit of Measure:</strong> physical measurement standard (linear meters, sq. decimeters, pcs, kg, liters, ml). Choose the smallest practical unit used during actual production or service jobs.</li><li><strong>Safety Threshold (Min Stock):</strong> buffer quantity that highlights the table row when stock runs critically low: <ul><li><em>Manual threshold:</em> a fixed number (e.g., alert when fewer than 5 units remain).</li><li><em>Adaptive auto-calculation:</em> entering <code>0</code> directs the system to evaluate your last 20 batch purchases and maintain a dynamic 20% safety margin.</li></ul></li></ul><h3 id="multiple-suppliers-web-bookmarks" tabindex="-1">Multiple Suppliers &amp; Web Bookmarks <a class="header-anchor" href="#multiple-suppliers-web-bookmarks" aria-label="Permalink to &quot;Multiple Suppliers &amp; Web Bookmarks&quot;">​</a></h3><p>Link multiple suppliers to a single inventory card (e.g., an overseas bulk wholesaler and a local retailer for quick restocks):</p><ul><li><strong>&quot;Make Primary&quot; (Pin):</strong> the primary URL appears directly inside the main warehouse table cell. Clicking the link opens the supplier&#39;s reorder portal in your browser instantly.</li><li><strong>&quot;Show in Table&quot;:</strong> alternative secondary vendors are tucked into a clean <code>(+N)</code> badge, keeping the operational view uncluttered.</li></ul><h3 id="warehouse-personalization-column-visibility" tabindex="-1">Warehouse Personalization &amp; Column Visibility <a class="header-anchor" href="#warehouse-personalization-column-visibility" aria-label="Permalink to &quot;Warehouse Personalization &amp; Column Visibility&quot;">​</a></h3><p>The gear icon button in the upper-right section of the warehouse toolbar opens the <strong>&quot;Warehouse Display Settings&quot;</strong> modal. This dialog allows flexible tailoring of your workspace:</p><ul><li><strong>Table Column Visibility:</strong> toggle columns for <em>SKU</em>, <em>Location</em>, <em>Min Stock</em>, <em>Notes</em>, <em>Photo</em>, and <em>Supplier</em> on or off depending on your monitor width;</li><li><strong>Quick-Add Form Fields:</strong> show or hide secondary fields in the rapid material entry form;</li><li><strong>Adaptive Safety Buffer:</strong> customize the exact percentage (from 1% to 100% of average monthly consumption) used for dynamic minimum stock threshold calculations.</li></ul><hr><h2 id="material-location-management-and-bin-tracking" tabindex="-1">Material Location Management and Bin Tracking <a class="header-anchor" href="#material-location-management-and-bin-tracking" aria-label="Permalink to &quot;Material Location Management and Bin Tracking&quot;">​</a></h2><p>In a busy workshop or repair center, searching for misplaced materials consumes valuable bench time. OmniCraft ERP includes a physical location directory that structures inventory across racks, shelves, and storage bins.</p><h3 id="purpose-and-storage-hierarchy" tabindex="-1">Purpose and Storage Hierarchy <a class="header-anchor" href="#purpose-and-storage-hierarchy" aria-label="Permalink to &quot;Purpose and Storage Hierarchy&quot;">​</a></h3><p>Location management connects digital inventory records with your physical workshop floor plan:</p><ol><li><strong>Precise Floor Navigation:</strong> Craftsmen and apprentices immediately see the exact shelf or storage drawer on the stock card and warehouse table (e.g., <em>&quot;Rack A, Shelf 2, Bin 04&quot;</em>).</li><li><strong>Error-Free Batch Assembly:</strong> When assigning production tasks or assembling repair work orders, designated bin addresses prevent mix-ups between similar leather hides, alloy types, or electrical components.</li><li><strong>Streamlined Cycle Counts:</strong> Physical inventory auditing proceeds systematically rack by rack without requiring a full workshop shutdown.</li></ol><h3 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h3><p>Before setting up bin addresses, establish a systematic workshop labeling convention: identify racks with letters, shelves with numbers, and component bins or organizers with two-digit codes.</p><h3 id="step-by-step-location-setup-and-material-assignment" tabindex="-1">Step-by-Step Location Setup and Material Assignment <a class="header-anchor" href="#step-by-step-location-setup-and-material-assignment" aria-label="Permalink to &quot;Step-by-Step Location Setup and Material Assignment&quot;">​</a></h3><ol><li><strong>Open the Locations Management Window:</strong><ul><li>When creating a new stock card via <strong>&quot;+&quot; (New Item)</strong> or editing an existing position, click the pencil icon button beside the <strong>&quot;Location / Shelf&quot;</strong> field;</li><li>The <strong>&quot;Manage Locations&quot;</strong> modal dialog opens.</li></ul></li><li><strong>Add a Physical Storage Location:</strong><ul><li>Enter the location name into the text input (e.g., <em>&quot;Rack 1 / Shelf B&quot;</em>, <em>&quot;Chemical Cabinet, Bay 3&quot;</em>);</li><li>Click <strong>&quot;Add&quot;</strong>. The location is registered immediately in your system catalog.</li></ul></li><li><strong>Edit and Rename Storage Zones:</strong><ul><li>If a rack is relocated or relabeled, click the pencil edit icon next to the location name in the list;</li><li>In the edit dialog, update the name in <strong>&quot;Name&quot;</strong> and click <strong>&quot;Save&quot;</strong>;</li><li>All inventory items linked to this location automatically reflect the updated address without manual re-linking.</li></ul></li><li><strong>Remove Retired Locations:</strong><ul><li>When storage shelving is decommissioned, click the red trash icon beside the location;</li><li>The system removes the location safely from quick-selection menus.</li></ul></li><li><strong>Assign Location and Inspect the Warehouse Table:</strong><ul><li>Click <strong>&quot;Close&quot;</strong> in the location dialog;</li><li>In the material card, select your created storage location from the dropdown menu;</li><li>Click <strong>&quot;Save&quot;</strong>. The location appears in the main warehouse table location column, speeding up filtering and material retrieval during batch assembly.</li></ul></li></ol><div class="tip custom-block"><p class="custom-block-title">Print Labels with Location Codes</p><p>When generating inventory tags via the &quot;Batch Label Printing&quot; tool, the software can print the designated location address in bold beneath the Code128 barcode. This enables labeling both material packaging and physical shelf bins for fast verification with a handheld barcode scanner.</p></div><hr><h2 id="batch-purchases-automated-logistics" tabindex="-1">Batch Purchases &amp; Automated Logistics <a class="header-anchor" href="#batch-purchases-automated-logistics" aria-label="Permalink to &quot;Batch Purchases &amp; Automated Logistics&quot;">​</a></h2><p>The core restocking operation is triggered by the <strong>&quot;Batch Material Purchase&quot;</strong> button (shopping cart icon in the top toolbar).</p><p>If someone removes a material after you fill out the form, the entire purchase stays unposted. Update the item list and post the batch again.</p><div class="warning custom-block"><p class="custom-block-title">Do not confuse purchases with inventory adjustments</p><p>Never enter purchased stock via manual inventory adjustments. Adjustments modify physical quantities on shelves without recalculating purchase price and without creating a payment record. All supplier invoices must be posted through &quot;Batch Purchase&quot;.</p></div><h3 id="equitable-freight-distribution-by-value" tabindex="-1">Equitable Freight Distribution by Value <a class="header-anchor" href="#equitable-freight-distribution-by-value" aria-label="Permalink to &quot;Equitable Freight Distribution by Value&quot;">​</a></h3><p>When a supplier ships a consolidated order, the freight invoice covers the entire shipment. Dividing delivery costs equally per item skews your margins: inexpensive supplies artificially spike in price, while premium materials are undervalued.</p><p>OmniCraft ERP enforces <strong>proportional freight distribution based on item value</strong>:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Purchased Item</th><th style="text-align:left;">Batch Value</th><th style="text-align:left;">Share of Invoice</th><th style="text-align:left;">Freight Share ($100 total delivery)</th><th style="text-align:left;">Final Batch Cost Basis</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>High-Value Material</strong> <em>(e.g. electric motor or leather)</em></td><td style="text-align:left;">$900.00</td><td style="text-align:left;"><code>90%</code></td><td style="text-align:left;"><strong>+ $90.00</strong></td><td style="text-align:left;"><strong>$990.00</strong></td></tr><tr><td style="text-align:left;"><strong>Low-Cost Consumable</strong> <em>(e.g. screws or tape)</em></td><td style="text-align:left;">$100.00</td><td style="text-align:left;"><code>10%</code></td><td style="text-align:left;"><strong>+ $10.00</strong></td><td style="text-align:left;"><strong>$110.00</strong></td></tr><tr><td style="text-align:left;"><strong>TOTAL:</strong></td><td style="text-align:left;"><strong>$1,000.00</strong></td><td style="text-align:left;"><code>100%</code></td><td style="text-align:left;"><strong>$100.00</strong></td><td style="text-align:left;"><strong>$1,100.00</strong></td></tr></tbody></table><p>Upon confirming the purchase, OmniCraft instantly:</p><ol><li>Receives exact physical quantities into shelf stock.</li><li>Updates each item&#39;s Moving Average Cost (MAC), including its fair share of delivery.</li><li>Generates two clear expense entries in the Cash Flow register: <em>&quot;Raw Material Purchase&quot;</em> and <em>&quot;Material Delivery&quot;</em>.</li></ol><hr><h2 id="warehouse-labeling-offline-barcode-printing" tabindex="-1">Warehouse Labeling &amp; Offline Barcode Printing <a class="header-anchor" href="#warehouse-labeling-offline-barcode-printing" aria-label="Permalink to &quot;Warehouse Labeling &amp; Offline Barcode Printing&quot;">​</a></h2><p>OmniCraft ERP features a built-in barcode label engine that operates 100% locally and offline without external cloud dependencies.</p><p>Labels can be generated individually from a material&#39;s card (printer icon) or printed in bulk for an entire storage aisle or selected materials list via <strong>&quot;Batch Label Printing&quot;</strong>.</p><h3 id="step-by-step-label-configuration-and-printing" tabindex="-1">Step-by-Step Label Configuration and Printing <a class="header-anchor" href="#step-by-step-label-configuration-and-printing" aria-label="Permalink to &quot;Step-by-Step Label Configuration and Printing&quot;">​</a></h3><ol><li><strong>Select Media Format:</strong> choose the target label dimension from the dropdown: <ul><li><strong>Direct Thermal Roll:</strong> standard self-adhesive thermal roll dimensions: <code>30×20</code> and <code>40×30</code> mm (for compact parts bins and hardware), universal <code>58×40</code> mm (optimal for shelves and storage boxes), as well as large <code>100×75</code> and <code>100×150</code> mm sizes for shipping containers and pallets.</li><li><strong>Die-cut A4 Sheets:</strong> pre-cut multi-label adhesive sheets (from 65 down to 4 labels per sheet) for standard laser and inkjet office printers.</li></ul></li><li><strong>Choose Encoding Mode:</strong> specify what data is encoded onto the tag: internal SKU barcode (Code128), direct supplier reorder web link, plain-text material specifications, or hybrid barcode + QR code layouts.</li><li><strong>Border Styling:</strong> configure perimeter borders—borderless (for pre-cut die-cut rolls), dashed cut lines (for scissor cutting from standard A4 paper), or solid decorative borders.</li><li><strong>Print Quantity:</strong> enter required label copies (from 1 up to 500 copies for batch box labeling).</li><li><strong>Output &amp; Print:</strong> clicking print generates an offline layout and hands it over to the native Windows printing system.</li></ol><h3 id="label-encoding-modes" tabindex="-1">Label Encoding Modes <a class="header-anchor" href="#label-encoding-modes" aria-label="Permalink to &quot;Label Encoding Modes&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Mode</th><th style="text-align:left;">Code Type</th><th style="text-align:left;">Practical Use Case</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>SKU Code</strong></td><td style="text-align:left;">Linear Code128 Barcode</td><td style="text-align:left;">Rapid inventory lookup using standard handheld USB/Bluetooth scanners</td></tr><tr><td style="text-align:left;"><strong>Supplier Reorder</strong></td><td style="text-align:left;">Direct Web URL QR Code</td><td style="text-align:left;">Scanning with a mobile phone camera opens the supplier&#39;s product page for immediate reordering</td></tr><tr><td style="text-align:left;"><strong>Material Spec Sheet</strong></td><td style="text-align:left;">Plain-text QR Code</td><td style="text-align:left;">Read technical specifications, shelf balance, and storage guidelines without opening a PC</td></tr><tr><td style="text-align:left;"><strong>Hybrid Mode</strong></td><td style="text-align:left;">Barcode + QR Code</td><td style="text-align:left;">Optimal for standard shelf tags starting at 58×40 mm</td></tr><tr><td style="text-align:left;"><strong>Text Only</strong></td><td style="text-align:left;">Clean high-contrast typography</td><td style="text-align:left;">Suitable for compact bins, vials, and hardware drawers (30×20 mm)</td></tr></tbody></table><h3 id="mechanical-printer-calibration-x-y-offset" tabindex="-1">Mechanical Printer Calibration (X / Y Offset) <a class="header-anchor" href="#mechanical-printer-calibration-x-y-offset" aria-label="Permalink to &quot;Mechanical Printer Calibration (X / Y Offset)&quot;">​</a></h3><p>Different printing hardware has physical feeding tolerances: standard office laser printers experience slight paper drag on A4 sheets, while direct thermal roll printers may drift slightly around label gaps.</p><p>The print dialog provides dedicated <strong>&quot;Printer Calibration (mm)&quot;</strong> fields:</p><ul><li><strong>Vertical Offset (Y, mm):</strong> shifts layout up or down (e.g., <code>-2.0</code> moves print output exactly 2 mm upward).</li><li><strong>Horizontal Offset (X, mm):</strong> centers print output perfectly within pre-die-cut adhesive borders.</li><li><strong>Border Styling:</strong> borderless (for pre-cut die-cut rolls), dashed cut lines (for scissor cutting from standard A4 paper), or solid decorative borders for product tags.</li></ul><p>Calibration parameters are saved once and automatically applied to all subsequent print runs.</p><hr><h2 id="stocktakes-waste-inventory-adjustments" tabindex="-1">Stocktakes, Waste &amp; Inventory Adjustments <a class="header-anchor" href="#stocktakes-waste-inventory-adjustments" aria-label="Permalink to &quot;Stocktakes, Waste &amp; Inventory Adjustments&quot;">​</a></h2><p>Beyond regular supplier receipts, daily workshop realities require stock reconciliation:</p><ol><li><strong>Physical Inventory Stocktake:</strong> during periodic shelf counts, enter actual counts on hand. OmniCraft logs variances (surplus or shortage) <strong>without distorting unit moving average cost (MAC)</strong>.</li><li><strong>Scrap &amp; Damage Write-offs:</strong> when discovering defects, transit damage, or cutting waste, write off materials with an attached explanation. The written-off value accurately reduces your balance sheet Capital.</li><li><strong>Audit Operations Log:</strong> every movement (receipt, reservation, production deduction, return, adjustment) is recorded in an immutable historical ledger complete with timestamps.</li></ol><hr><h2 id="troubleshooting-common-pitfalls" tabindex="-1">Troubleshooting &amp; Common Pitfalls <a class="header-anchor" href="#troubleshooting-common-pitfalls" aria-label="Permalink to &quot;Troubleshooting &amp; Common Pitfalls&quot;">​</a></h2><div class="faq-grid"><details class="faq-item"><summary class="faq-summary">What should I do if an intake invoice had the wrong purchase price or omitted freight charges?</summary><div class="faq-content"><p>Click the operations log icon on the material row, find the corresponding intake record, and open it for editing. Adjust the purchase total or freight amount—the moving average cost (MAC) engine instantly updates the unit valuation across all dependent batches.</p></div></details><details class="faq-item"><summary class="faq-summary">Why are thermal label prints misaligned or cutting off edges?</summary><div class="faq-content"><p>Open the &quot;Printer Calibration (mm)&quot; section within the print dialog and define X and Y coordinate offsets (e.g., -2.0 mm vertical shift). These offsets persist in application memory and apply automatically to all future label rolls.</p></div></details><details class="faq-item"><summary class="faq-summary">How do I resolve a negative raw material balance?</summary><div class="faq-content"><p>Negative balances occur when shop floor orders finish before intake paperwork is logged. Enter the supplier receipt using the actual arrival date—stock counts reconcile immediately and production valuations update.</p></div></details></div>',74))])}const w=i(h,[["render",g]]);export{k as __pageData,w as default};
